  "Class VI|||English|||Sound Detective – Class VI": {
    "title": "Sound Detective – Class VI",
    "audio_script": "The science room was silent. Then a thin wire was stretched across a wooden box and a cup was fixed to its middle. Ravi plucked the wire and immediately the cup jumped. 'The wire is loose,' he said, so he tightened it by turning the peg one full turn. When he plucked again the cup jumped much higher. Then he added a thicker wire and the cup hardly moved at all.",
    "audio": "audio/sound-detective-class-vi.wav",
    "audio_seconds": 13.25,
    "instructions": [],
    "questions": [
      {
        "question": "[Class VI English - Sound Detective – Class VI] What did Ravi do first?",
        "options": [
          "Option A: He tightened the peg",
          "Option B: He added a thicker wire",
          "Option C: He fixed the cup",
          "Option D: He plucked the wire"
        ],
        "answer": "Option D: He plucked the wire",
        "explanation": "Ravi plucked the wire and the cup jumped.",
        "image": "images/listening/sound-detective-class-vi-q0.svg"
      },
      {
        "question": "[Class VI English - Sound Detective – Class VI] What happened after he tightened the wire?",
        "options": [
          "Option A: The cup fell down",
          "Option B: The cup jumped much higher",
          "Option C: The cup stopped moving",
          "Option D: The wire broke"
        ],
        "answer": "Option B: The cup jumped much higher",
        "explanation": "When he plucked again the cup jumped much higher.",
        "image": "images/listening/sound-detective-class-vi-q1.svg"
      },
      {
        "question": "[Class VI English - Sound Detective – Class VI] What happened when he added a thicker wire?",
        "options": [
          "Option A: The cup jumped higher",
          "Option B: The cup broke",
          "Option C: The wire became longer",
          "Option D: The cup hardly moved"
        ],
        "answer": "Option D: The cup hardly moved",
        "explanation": "With a thicker wire the cup hardly moved at all.",
        "image": "images/listening/sound-detective-class-vi-q2.svg"
      }
    ]
  },
