    "title": "Accent & Stress Spotter",
    "audio_script": "In British English, the word 'schedule' is usually pronounced 'SHED yool', while many Indian speakers say 'SKED yool'. Both are understood. In British English 'ask' is 'ASK', but in American English it is 'ASK'. Notice that the same two-syllable word 'thirteen' changes its stress between British and Indian English. When you meet an unfamiliar word, say it aloud both ways and use the one you hear most often.",
